<script setup lang="ts">import {computed,provide,useId} from 'vue';import H0Label from '../Typography/H0Label.vue';import H0Description from '../Typography/H0Description.vue';import H0ErrorMessage from '../Typography/H0ErrorMessage.vue';import {h0FieldKey} from './Field.context';import type {H0FieldProps} from './Field.types';defineOptions({name:'H0Field'});const props=withDefaults(defineProps<H0FieldProps>(),{id:'',name:'',label:'',required:false,disabled:false,error:'',hint:'',orientation:'vertical'});const generated=useId();const id=computed(()=>props.id||`h-field-${generated}`);const messageId=computed(()=>`${id.value}-message`);provide(h0FieldKey,{id,name:computed(()=>props.name),label:computed(()=>props.label),required:computed(()=>props.required),disabled:computed(()=>props.disabled),error:computed(()=>props.error),hint:computed(()=>props.hint),messageId});const controlAttrs=computed(()=>({id:id.value,name:props.name||undefined,disabled:props.disabled||undefined,required:props.required||undefined,'aria-invalid':Boolean(props.error),'aria-describedby':props.error||props.hint?messageId.value:undefined,'aria-errormessage':props.error?messageId.value:undefined}))</script>
<template><div data-h0n-component="field" class="h-field" :class="[`h-field--${orientation}`,error&&'h-field--error',disabled&&'h-field--disabled']"><H0Label v-if="label||$slots.label" :for="id" :required="required"><slot name="label">{{label}}</slot></H0Label><div class="h-field__control"><slot :control-attrs="controlAttrs" :id="id" :message-id="messageId" :invalid="Boolean(error)" /></div><H0ErrorMessage v-if="error||$slots.error" :id="messageId" role="alert"><slot name="error">{{error}}</slot></H0ErrorMessage><H0Description v-else-if="hint||$slots.hint" :id="messageId"><slot name="hint">{{hint}}</slot></H0Description></div></template>
<style scoped>.h-field{display:grid;font-family:var(--h0n-ui-font-family);gap:var(--h0n-ui-spacing-sm);min-width:0}.h-field--horizontal{align-items:start;grid-template-columns:minmax(120px,auto) minmax(0,1fr)}.h-field--horizontal>:not(.h-field__control){grid-column:2}.h-field--disabled{opacity:var(--h0n-ui-disabled-opacity)}.h-field__control{min-width:0}</style>
